72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (!normalizeNewOwner(owner)) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (dailyLimitReached(owner.getRegistrationDate())) {
116	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
117	        }
118	        if (cityIsAtCapacity(owner.getCity())) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (emailAlreadyUsed(owner.getEmail())) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        Optional<Owner> householdMember = findHouseholdMember(owner);
128	        if (householdMember.isPresent()) {
129	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
130	                return new ResponseEntity<>(HttpStatus.CONFLICT);
131	            }
132	            joinHousehold(owner, householdMember.get());
133	        }
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
135	        owner.setNamesakeCount(countNamesakes(owner));
136	        owner.setMembershipNumber(membershipNumber(owner));
137	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
138	        owner.setHouseholdSize(householdSize(owner));
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
160	        String email = ownerFieldsDto.getEmail();
161	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
