227	    }
228	
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner != null) {
235	            Pet pet = owner.getPet(petId);
236	            if (pet != null) {
237	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    /**
244	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
245	     * the canonical form each stored value must take: the address is trimmed,
246	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
247	     * telephone is converted to E.164, any email is lower-cased and a missing
248	     * registration date defaults to today. Field-level rejections are reported here
249	     * rather than inline in {@link #addOwner}, and normalisation runs before any
250	     * household comparison so those comparisons see the canonical values.
251	     *
252	     * @param owner the freshly-mapped owner to normalise
253	     * @return {@code true} if the fields are valid, or {@code false} if the address
254	     *         is blank after normalisation or the telephone cannot form a valid
255	     *         E.164 number, in which case the request must be rejected with
256	     *         {@code 400 Bad Request}
257	     */
258	    private boolean normalizeNewOwner(Owner owner) {
259	        String address = Owner.normalizeAddress(owner.getAddress());
260	        if (address.isEmpty()) {
261	            return false;
262	        }
263	        owner.setAddress(address);
264	        String telephone = toE164(owner.getTelephone());
265	        if (telephone == null) {
266	            return false;
267	        }
268	        owner.setTelephone(telephone);
269	        if (owner.getEmail() != null) {
270	            owner.setEmail(owner.getEmail().toLowerCase());
271	        }
272	        if (owner.getRegistrationDate() == null) {
273	            owner.setRegistrationDate(LocalDate.now());
274	        }
275	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
276	        return true;
277	    }
278	
279	    /**
280	     * Roll the given date forward to the next business day when it falls on a
281	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
282	     * weekday is returned unchanged. Applied to the effective registration date
283	     * (whether supplied in the request or defaulted to the server date) so that
284	     * every value derived from it uses the adjusted business day.
285	     *
286	     * @param date the effective registration date
287	     * @return the same date if it is a weekday, otherwise the next Monday
288	     */
289	    private static LocalDate rollToBusinessDay(LocalDate date) {
290	        switch (date.getDayOfWeek()) {
291	            case SATURDAY:
292	                return date.plusDays(2);
293	            case SUNDAY:
294	                return date.plusDays(1);
295	            default:
296	                return date;
297	        }
298	    }
299	
300	    /**
301	     * Determine whether the given (already lower-cased) email is already used by any
302	     * existing owner, compared on the lower-cased email value. Owners without an email
303	     * never match, so a {@code null} or blank candidate email is never a duplicate.
304	     *
305	     * @param email the candidate owner's normalised (lower-cased) email
306	     * @return {@code true} if an existing owner already uses that email
307	     */
308	    private boolean emailAlreadyUsed(String email) {
309	        if (email == null || email.isBlank()) {
310	            return false;
311	        }
312	        return this.clinicService.findAllOwners().stream()
313	            .map(Owner::getEmail)
314	            .filter(existing -> existing != null)
315	            .anyMatch(existing -> existing.toLowerCase().equals(email));
316	    }
317	
318	    /**
319	     * Find an existing owner that belongs to the same household as the given owner,
320	     * i.e. shares the same last name and address (compared case-insensitively with
321	     * runs of whitespace collapsed to a single space).
322	     *
323	     * @param owner the candidate owner being created
324	     * @return the matching existing owner, or empty if none exists
325	     */
326	    private Optional<Owner> findHouseholdMember(Owner owner) {
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> existing.sameHouseholdAs(owner))
329	            .findFirst();
330	    }
331	
332	    /**
333	     * Assign the joining owner and an existing household member the same stable
334	     * household identifier. The identifier is derived deterministically from the
335	     * shared household key (last name + address, normalised), so every owner in a
336	     * household resolves to the same value; the existing member is updated when it
337	     * does not already carry it.
338	     *
339	     * @param owner    the owner being created
340	     * @param existing an existing owner in the same household
341	     */
342	    private void joinHousehold(Owner owner, Owner existing) {
343	        String householdId = UUID
344	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
345	        owner.setHouseholdId(householdId);
346	        if (!householdId.equals(existing.getHouseholdId())) {
347	            existing.setHouseholdId(householdId);
348	            this.clinicService.saveOwner(existing);
349	        }
350	    }
351	
352	    /**
353	     * Count how many owners belong to the given owner's household once this create
354	     * completes: the owners that already share its {@code householdId} plus the owner
355	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
356	     * so the household identifier (and any existing member updated to it) is already in
357	     * place. An owner that has not joined a household (no {@code householdId}) is a
358	     * household of one.
359	     *
360	     * @param owner the candidate owner being created, after household resolution
361	     * @return the household member count after this create (at least {@code 1})
362	     */
363	    private int householdSize(Owner owner) {
364	        String householdId = owner.getHouseholdId();
365	        if (householdId == null) {
366	            return 1;
367	        }
368	        long existing = this.clinicService.findAllOwners().stream()
369	            .filter(other -> householdId.equals(other.getHouseholdId()))
370	            .count();
371	        return (int) existing + 1;
372	    }
373	
374	    /**
375	     * Count the existing owners that share the given owner's first and last name,
376	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
377	     * before the new owner is saved, so the result reflects only owners that
378	     * already existed at creation time.
379	     *
380	     * @param owner the candidate owner being created
381	     * @return the number of existing namesakes
382	     */
383	    private int countNamesakes(Owner owner) {
384	        String firstName = normalizeName(owner.getFirstName());
385	        String lastName = normalizeName(owner.getLastName());
386	        return (int) this.clinicService.findAllOwners().stream()
387	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
388	                && normalizeName(existing.getLastName()).equals(lastName))
389	            .count();
390	    }
391	
392	    private static String normalizeName(String value) {
393	        return value == null ? "" : value.trim().toLowerCase();
394	    }
395	
396	    /**
397	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
398	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
399	     * first three letters of the given last name and NNNN a per-city 4-digit
400	     * zero-padded sequence equal to one more than the number of owners already in
401	     * that city (e.g. {@code SYD-SMI-0007}).
402	     *
403	     * @param city     the owner's city
404	     * @param lastName the owner's last name
405	     * @return the assigned customer code
406	     */
407	    /**
408	     * Determine whether the given city has already reached its owner capacity, i.e.
409	     * it already contains 50 or more existing owners (compared case-insensitively
410	     * with surrounding whitespace trimmed). A new owner may not be created in a city
411	     * that is at capacity.
412	     *
413	     * @param city the candidate owner's city
414	     * @return {@code true} if the city already holds 50 or more owners
415	     */
416	    private boolean cityIsAtCapacity(String city) {
417	        String normalizedCity = normalizeName(city);
418	        long count = this.clinicService.findAllOwners().stream()
419	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
420	            .count();
421	        return count >= 50;
422	    }
423	
424	    /**
425	     * Determine whether the daily owner-creation limit has already been reached, i.e.
426	     * 100 or more owners already carry the given registration date. A new owner may
427	     * not be created once that day's cap is reached.
428	     *
429	     * @param registrationDate the registration date the new owner would be created with
430	     * @return {@code true} if 100 or more existing owners share that registration date
431	     */
432	    private boolean dailyLimitReached(LocalDate registrationDate) {
433	        long count = this.clinicService.findAllOwners().stream()
434	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
435	            .count();
436	        return count >= 100;
437	    }
438	
439	    /**
440	     * Determine whether more than 80 owners have already been created for the given
441	     * registration date, i.e. strictly more than 80 existing owners carry that date.
442	     * Evaluated before the new owner is saved, so it reflects only owners that
443	     * already existed at creation time.
444	     *
445	     * @param registrationDate the registration date the new owner would be created with
446	     * @return {@code true} if more than 80 existing owners share that registration date
447	     */
448	    private boolean bulkSignupWarning(LocalDate registrationDate) {
449	        long count = this.clinicService.findAllOwners().stream()
450	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
451	            .count();
452	        return count > 80;
453	    }
454	
455	    private String nextCustomerCode(String city, String lastName) {
456	        String city3 = prefix3(city);
457	        String last3 = prefix3(lastName);
458	        long sequence = this.clinicService.findAllOwners().stream()
459	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
460	            .count() + 1L;
461	        return String.format("%s-%s-%04d", city3, last3, sequence);
462	    }
463	
464	    private static String prefix3(String value) {
465	        String v = value == null ? "" : value;
466	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
467	    }
468	
469	    /**
470	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
471	     * where {@code <customerCode>} is the owner's already-assigned customer code and
472	     * YY is the last two digits of the registration date's year (e.g.
